{
  "findings": [
    {
      "check_id": "CKV_AWS_277",
      "title": "Ensure no security groups allow ingress from 0.0.0.0:0 to port -1",
      "resource": "aws_security_group.vault",
      "severity": "MEDIUM",
      "explanation": "The security group 'vault' allows ingress from 0.0.0.0/0 to any port in the range defined by var.ingress_ports, potentially exposing it to the internet if var.ingress_ports includes -1 or a wide range of ports."
    },
    {
      "check_id": "CKV_AWS_24",
      "title": "Ensure no security groups allow ingress from 0.0.0.0:0 to port 22",
      "resource": "aws_security_group.vault",
      "severity": "MEDIUM",
      "explanation": "The security group 'vault' allows ingress from 0.0.0.0/0 to any port in the range defined by var.ingress_ports, potentially exposing SSH (port 22) to the internet if 22 is included in var.ingress_ports."
    },
    {
      "check_id": "CKV_AWS_260",
      "title": "Ensure no security groups allow ingress from 0.0.0.0:0 to port 80",
      "resource": "aws_security_group.vault",
      "severity": "MEDIUM",
      "explanation": "The security group 'vault' allows ingress from 0.0.0.0/0 to any port in the range defined by var.ingress_ports, potentially exposing HTTP (port 80) to the internet if 80 is included in var.ingress_ports."
    },
    {
      "check_id": "CKV_AWS_25",
      "title": "Ensure no security groups allow ingress from 0.0.0.0:0 to port 3389",
      "resource": "aws_security_group.vault",
      "severity": "MEDIUM",
      "explanation": "The security group 'vault' allows ingress from 0.0.0.0/0 to any port in the range defined by var.ingress_ports, potentially exposing RDP (port 3389) to the internet if 3389 is included in var.ingress_ports."
    }
  ],
  "patched_code": "resource \"aws_security_group\" \"vault\" {\n  name        = \"vault\"\n  description = \"Ingress for Vault\"\n  vpc_id      = aws_vpc.my_vpc.id\n  dynamic \"ingress\" {\n    iterator = port\n    for_each = var.ingress_ports\n    content {\n      from_port   = port.value\n      to_port     = port.value\n      protocol    = \"tcp\"\n      cidr_blocks = [\"10.0.0.0/8\"]\n    }\n  }\n}",
  "fix_summary": "Restricted the ingress cidr_blocks to a private IP range (10.0.0.0/8) to prevent exposure to the internet."
}
